// A "cold" payload is deliberately carried in each AoS record but never read
// by the hot update. This increases bytes transferred per sequential scan.
struct ParticleAoS {
    float x{}, y{}, z{}, mass{};
    std::array<float, 12> debug_and_editor_metadata{};
