namespace allmight::asset_query {

void require(bool valid, const char* what) {
    if (!valid) throw std::runtime_error(what); // valid even with -DNDEBUG
}

// An owning snapshot is a separate lifetime from the live asset registry.
// Tombstones stay in this example to make a custom forward iterator useful.
struct Row {
    std::string name;
    std::size_t bytes;
    bool live;
};

std::vector<Row> make_snapshot() {
    return {{"brick.mesh", 48, true}, {"retired.tex", 512, false},
            {"sky.tex", 64, true}, {"ui.tex", 16, true},
            {"terrain.mesh", 128, true}, {"rock.mesh", 48, true}};
}

// Custom multi-pass forward iterator. It borrows the Row vector and skips
// tombstones, but does not own the vector or preserve validity on reallocation.
class LiveRowIterator {
    const std::vector<Row>* rows_ = nullptr;
    std::size_t pos_ = 0;

    void skip_dead() noexcept {
        if (!rows_) return;
        while (pos_ < rows_->size() && !(*rows_)[pos_].live) ++pos_;
    }
public:
    using iterator_concept = std::forward_iterator_tag;
    using iterator_category = std::forward_iterator_tag;
    using value_type = Row;
    using difference_type = std::ptrdiff_t;
    using reference = const Row&;

    LiveRowIterator() = default;
    LiveRowIterator(const std::vector<Row>& rows, std::size_t pos)
        : rows_(&rows), pos_(pos) { skip_dead(); }
    reference operator*() const noexcept { return (*rows_)[pos_]; }
    const Row* operator->() const noexcept { return std::addressof(**this); }
    LiveRowIterator& operator++() noexcept { ++pos_; skip_dead(); return *this; }
    LiveRowIterator operator++(int) noexcept { auto old = *this; ++*this; return old; }
    friend bool operator==(const LiveRowIterator&, const LiveRowIterator&) = default;
};
static_assert(std::forward_iterator<LiveRowIterator>);
static_assert(!std::bidirectional_iterator<LiveRowIterator>);
static_assert(!std::contiguous_iterator<LiveRowIterator>);

// begin() and end() are discovered in range-based for's exposition model.
// A range-for keeps its range expression alive for the loop, but a returned
// view or stored iterator still requires explicit owner-lifetime reasoning.
struct LiveRows {
    const std::vector<Row>* owner;
    LiveRowIterator begin() const { return LiveRowIterator{*owner, 0}; }
    LiveRowIterator end() const { return LiveRowIterator{*owner, owner->size()}; }
};
static_assert(std::ranges::forward_range<LiveRows>);

// An illustrative C++ allocator: typed allocate/deallocate must be paired.
// The shared statistics object survives copies/rebinds of the allocator.
struct AllocationStats {
    std::size_t allocations = 0;
    std::size_t deallocations = 0;
    std::size_t allocated_bytes = 0;
};
template<class T>
struct TrackingAllocator {
    using value_type = T;
    std::shared_ptr<AllocationStats> stats;
    TrackingAllocator() : stats(std::make_shared<AllocationStats>()) {}
    explicit TrackingAllocator(std::shared_ptr<AllocationStats> s) : stats(std::move(s)) {}
    template<class U>
    TrackingAllocator(const TrackingAllocator<U>& other) noexcept : stats(other.stats) {}
    T* allocate(std::size_t count) {
        if (count > std::allocator_traits<std::allocator<T>>::max_size(std::allocator<T>{}))
            throw std::bad_array_new_length();
        auto* raw = std::allocator<T>{}.allocate(count);
        ++stats->allocations;
        stats->allocated_bytes += count * sizeof(T);
        return raw;
    }
    void deallocate(T* ptr, std::size_t count) noexcept {
        ++stats->deallocations;
        std::allocator<T>{}.deallocate(ptr, count);
    }
    template<class U> friend struct TrackingAllocator;
    template<class U> bool operator==(const TrackingAllocator<U>& rhs) const noexcept {
        return stats == rhs.stats;
    }
};

// std::pmr moves the allocation-policy choice to runtime. The resource must
// outlive every container and object retaining a pointer to it.
class CountingMemoryResource final : public std::pmr::memory_resource {
    std::pmr::memory_resource* upstream_;
public:
    std::size_t allocated_blocks = 0;
    std::size_t freed_blocks = 0;
    std::size_t allocated_bytes = 0;
    explicit CountingMemoryResource(std::pmr::memory_resource* upstream)
        : upstream_(upstream) {}
private:
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        void* ptr = upstream_->allocate(bytes, alignment);
        ++allocated_blocks;
        allocated_bytes += bytes;
        return ptr;
    }
    void do_deallocate(void* ptr, std::size_t bytes, std::size_t alignment) override {
        ++freed_blocks;
        upstream_->deallocate(ptr, bytes, alignment);
    }
    bool do_is_equal(const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }
};

// Function objects and lambdas give equivalent call semantics here, but
// code generation/allocations/capture size need MEASUREMENT, not slogans.
struct AtLeastBytes {
    std::size_t threshold;
    bool operator()(const Row& row) const noexcept { return row.bytes >= threshold; }
};

void run() {
    auto rows = make_snapshot();
    LiveRows live{&rows};
    std::size_t visits = 0;
    std::size_t total = 0;
    for (const Row& row : live) { // range-based for begin/end, not indexing
        ++visits;
        total += row.bytes;
    }
    require(visits == 5 && total == 304, "custom forward iterator skips tombstones");

    // Filter/transform adaptor creation is lazy. We can observe that neither
    // predicate nor transform runs until the range is iterated.
    std::size_t predicate_calls = 0;
    std::size_t projection_calls = 0;
    auto pipeline = std::views::all(rows)
        | std::views::filter([&](const Row& row) {
              ++predicate_calls;
              return row.live && row.bytes >= 48;
          })
        | std::views::transform([&](const Row& row) {
              ++projection_calls;
              return row.name;
          });
    require(predicate_calls == 0 && projection_calls == 0, "views compose lazily");
    std::vector<std::string> names;
    for (const auto& name : pipeline) names.push_back(name);
    require(names == std::vector<std::string>({"brick.mesh", "sky.tex",
                                               "terrain.mesh", "rock.mesh"}),
            "filter and transform produce the correct sequence");
    require(predicate_calls > 0 && projection_calls == 4,
            "predicates/transform execute during traversal");

    // Borrowed means iterators can outlive the range VIEW under its contract;
    // it does not mean the underlying vector's owner is kept alive.
    static_assert(std::ranges::borrowed_range<std::ranges::ref_view<std::vector<Row>>>);
    static_assert(!std::ranges::borrowed_range<std::vector<Row>>);
    static_assert(!std::ranges::borrowed_range<std::ranges::owning_view<std::vector<Row>>>);
    auto owned = std::views::all(make_snapshot()); // owns its vector in the view
    require(std::ranges::distance(owned) == 6, "rvalue vector becomes owning view");

    // A projection is supplied separately from a comparator: ranges::find
    // compares row.name, not the Row object or an allocated name list.
    auto located = std::ranges::find(rows, std::string_view{"sky.tex"}, &Row::name);
    require(located != rows.end() && located->bytes == 64,
            "projected ranges::find locates the named asset");
    auto sorted = rows;
    std::ranges::sort(sorted, std::less<>{}, &Row::bytes);
    require(sorted.front().bytes == 16 && sorted.back().bytes == 512,
            "projected ranges::sort uses byte count");

    AtLeastBytes functor{48};
    auto equivalent_lambda = [threshold = std::size_t{48}](const Row& row) noexcept {
        return row.bytes >= threshold;
    };
    require(std::ranges::count_if(rows, functor) ==
            std::ranges::count_if(rows, equivalent_lambda),
            "functor and captured lambda express same predicate");

    auto stats = std::make_shared<AllocationStats>();
    {
        std::vector<std::size_t, TrackingAllocator<std::size_t>> tracked{
            TrackingAllocator<std::size_t>{stats}};
        tracked.reserve(5);
        for (const Row& row : live) tracked.push_back(row.bytes);
        require(std::accumulate(tracked.begin(), tracked.end(), std::size_t{0}) == 304,
                "custom allocator does not change vector's value semantics");
        require(stats->allocations > 0 && stats->allocated_bytes >= 5*sizeof(std::size_t),
                "custom allocator observes requests");
    }
    require(stats->allocations == stats->deallocations,
            "typed allocator allocations paired by vector lifetime");

    CountingMemoryResource resource{std::pmr::new_delete_resource()};
    {
        std::pmr::vector<std::size_t> sizes{&resource};
        sizes.reserve(5);
        for (const Row& row : live) sizes.push_back(row.bytes);
        std::pmr::unordered_map<std::pmr::string, std::size_t> index{&resource};
        for (const Row& row : live)
            index.emplace(std::pmr::string{row.name, &resource}, row.bytes);
        require(index.size() == 5 && index.at(std::pmr::string{"sky.tex", &resource}) == 64,
                "pmr unordered_map uses resource for nodes/buckets");
        require(std::accumulate(sizes.begin(), sizes.end(), std::size_t{0}) == 304,
                "pmr vector and custom allocator produce same data result");
        require(resource.allocated_blocks > 0, "pmr resource intercepts allocation");
    }
    require(resource.allocated_blocks == resource.freed_blocks,
            "ordinary upstream resource releases deallocated blocks");

    CountingMemoryResource arena_upstream{std::pmr::new_delete_resource()};
    alignas(std::max_align_t) std::array<std::byte, 128> scratch{};
    {
        std::pmr::monotonic_buffer_resource arena{scratch.data(), scratch.size(),
                                                   &arena_upstream};
        {
            std::pmr::vector<std::uint64_t> pixels{&arena};
            pixels.resize(2048, 7); // exceeds scratch, must ask upstream
            require(pixels.size() == 2048 && pixels[2000] == 7,
                    "monotonic arena supplies live vector storage");
            require(arena_upstream.allocated_blocks > 0,
                    "exhausting stack scratch delegates upstream");
        }
        // pixels' destructor can call deallocate, but monotonic arena does
        // not return its blocks individually; release happens in bulk.
        require(arena_upstream.freed_blocks == 0,
                "monotonic deallocation doesn't return upstream blocks now");
    }
    require(arena_upstream.allocated_blocks == arena_upstream.freed_blocks,
            "arena destruction returns its upstream allocations");

    alignas(std::max_align_t) std::array<std::byte, 64> fixed_scratch{};
    std::pmr::monotonic_buffer_resource bounded{fixed_scratch.data(),
                                                fixed_scratch.size(),
                                                std::pmr::null_memory_resource()};
    bool exhausted = false;
    try {
        std::pmr::vector<std::uint64_t> huge{&bounded};
        huge.resize(2048, 2);
    } catch (const std::bad_alloc&) { exhausted = true; }
    require(exhausted, "fixed arena plus null upstream detects capacity exhaustion");
    std::cout << "asset_ranges_pmr_lab: all checks passed\n";
}
} // namespace allmight::asset_query

int main() {
    try { allmight::asset_query::run(); }
    catch (const std::exception& error) {
        std::cerr << "asset_ranges_pmr_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// Executable witnesses for four first-use teaching bridges.
// Build: c++ -std=c++20 -O2 -Wall -Wextra -Wpedantic -Werror
//        tools/labs/first_use_contract_lab.cpp -o /tmp/first_use && /tmp/first_use
#include <array>
#include <algorithm>
#include <stdexcept>
#include <cmath>
#include <cstdint>
#include <limits>
#include <optional>
#include <utility>

// Keep validation enabled when NDEBUG removes ordinary assert() checks.
void require(bool condition) {
    if (!condition) throw std::runtime_error("first-use contract violated");
}

struct Vec2 { double x, y; };
struct Coordinates { double first, second, residual; };

// Solve [b1 b2] * c = world without constructing the inverse matrix.
// This is a teaching-sized 2x2 pivoted elimination, not a general LAPACK replacement.
std::optional<Coordinates> recover_coordinates(Vec2 b1, Vec2 b2, Vec2 world) {
    if (!std::isfinite(b1.x) || !std::isfinite(b1.y) ||
        !std::isfinite(b2.x) || !std::isfinite(b2.y) ||
        !std::isfinite(world.x) || !std::isfinite(world.y)) return std::nullopt;
    double a[2][3] = {{b1.x, b2.x, world.x}, {b1.y, b2.y, world.y}};
    const double scale = std::max({std::abs(b1.x), std::abs(b1.y),
                                   std::abs(b2.x), std::abs(b2.y)});
    if (scale == 0 || !std::isfinite(scale)) return std::nullopt;
    // The threshold is relative to the input matrix, not a fixed world-space distance.
    const double threshold = 32 * std::numeric_limits<double>::epsilon() * scale;
    for (int col = 0; col != 2; ++col) {
        int pivot = (std::abs(a[1][col]) > std::abs(a[col][col])) ? 1 : col;
        // Only row 1 can replace row 0 on the first pivot. At col 1, pivot stays 1.
        if (col == 1) pivot = 1;
        if (!(std::abs(a[pivot][col]) > threshold)) return std::nullopt;
        if (pivot != col) for (int j = 0; j != 3; ++j) std::swap(a[col][j], a[pivot][j]);
        if (col == 0) {
            const double m = a[1][0] / a[0][0];
            a[1][1] -= m * a[0][1];
            a[1][2] -= m * a[0][2];
            a[1][0] = 0;
        }
    }
    const double second = a[1][2] / a[1][1];
    const double first = (a[0][2] - a[0][1] * second) / a[0][0];
    const double dx = b1.x * first + b2.x * second - world.x;
    const double dy = b1.y * first + b2.y * second - world.y;
    if (!std::isfinite(first) || !std::isfinite(second) ||
        !std::isfinite(dx) || !std::isfinite(dy)) return std::nullopt;
    return Coordinates{first, second, std::hypot(dx, dy)};
}

struct Item { std::uint32_t key; std::uint32_t identity; };

// Stable two-bit radix sort. Only pointers are swapped: no in-place scatter.
template <std::size_t N>
std::array<Item, N> stable_two_bit_radix(std::array<Item, N> initial) {
    std::array<Item, N> scratch{};
    auto* read = &initial;
    auto* write = &scratch;
    for (unsigned bit = 0; bit != 2; ++bit) {
        std::size_t zeros = 0;
        for (const Item& item : *read) zeros += ((item.key >> bit) & 1u) == 0u;
        std::size_t next_zero = 0, next_one = zeros;
        for (const Item& item : *read) {
            // Each item has one disjoint destination. Relative order within a bin survives.
            const bool one = ((item.key >> bit) & 1u) != 0u;
            (*write)[one ? next_one++ : next_zero++] = item;
        }
        std::swap(read, write);
    }
    return *read; // This also works for an odd number of passes if the loop changes.
}

struct Splat { double q, opacity; std::array<double, 3> color; };
struct Composite { std::array<double, 3> color; double transmittance; };

// Input splats must already be sorted front-to-back in one declared depth convention.
// Color is linear and premultiplied into the accumulated result by alpha at each step.
std::optional<Composite> composite_splats(const Splat* splats, std::size_t count) {
    Composite out{{0, 0, 0}, 1};
    for (std::size_t i = 0; i < count; ++i) {
        const Splat& s = splats[i];
        if (!std::isfinite(s.q) || s.q < 0 || !std::isfinite(s.opacity) ||
            s.opacity < 0 || s.opacity > 1) return std::nullopt;
        for (double component : s.color)
            if (!std::isfinite(component) || component < 0 || component > 1)
                return std::nullopt;
        if (s.q > 9) continue; // Deliberate truncated footprint, not zero Gaussian support.
        const double alpha = std::clamp(s.opacity * std::exp(-0.5 * s.q), 0.0, 0.999);
        for (int ch = 0; ch != 3; ++ch)
            out.color[ch] += out.transmittance * alpha * s.color[ch];
        out.transmittance *= (1.0 - alpha);
        if (out.transmittance < 1e-4) break; // Bounded omitted color under [0,1] assumption.
    }
    return out; // Background, if any, adds T * background in the same linear space.
}

// A deterministic quadrature of the expectation of a two-technique MIS estimator.
// Both PDFs have full support in the open interval (0,1); f(x) = x^2.
double expected_mis_integral() {
    constexpr int slices = 10000;
    double total = 0;
    for (int i = 0; i < slices; ++i) {
        const double x = (i + 0.5) / slices;
        const double pa = 2 * x, pb = 2 * (1 - x);
        const double wa = (pa * pa) / (pa * pa + pb * pb);
        const double wb = 1 - wa;
        const double f = x * x;
        // p_a * (w_a f / p_a) + p_b * (w_b f / p_b): the two expectations.
        total += (pa * (wa * f / pa) + pb * (wb * f / pb)) / slices;
    }
    return total;
}

int main() {
    const auto c = recover_coordinates({1, 0}, {1, 1}, {3, 2});
    require(c && std::abs(c->first - 1) < 1e-12 &&
           std::abs(c->second - 2) < 1e-12 && c->residual < 1e-12);
    require(!recover_coordinates({1, 0}, {1, 0}, {3, 2}));

    auto sorted = stable_two_bit_radix<5>({{{3, 0}, {1, 1}, {2, 2}, {0, 3}, {2, 4}}});
    const std::array<std::uint32_t, 5> expected_keys{0, 1, 2, 2, 3};
    for (std::size_t i = 0; i < sorted.size(); ++i) require(sorted[i].key == expected_keys[i]);
    require(sorted[2].identity == 2 && sorted[3].identity == 4); // Stability.

    const std::array<Splat, 2> front_to_back{{{0, 0.6, {1, 0, 0}},
                                              {0, 0.5, {0, 0, 1}}}};
    const auto composed = composite_splats(front_to_back.data(), front_to_back.size());
    require(composed && std::abs(composed->color[0] - 0.6) < 1e-12 &&
           std::abs(composed->color[2] - 0.2) < 1e-12 &&
           std::abs(composed->transmittance - 0.2) < 1e-12);
    require(std::abs(expected_mis_integral() - 1.0 / 3.0) < 1e-8);
}

// AllMight M013 / Parts 201-216: generic, constrained asset preparation.
// C++20. This is a CPU-side laboratory; it does not use Vulkan or Metal.
#include <array>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <limits>
#include <optional>
#include <stdexcept>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>
#include <concepts>

namespace allmight {

void require(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message); // also works with NDEBUG
}

// A mesh stores indices. Two constructors record whether the incoming vector
// was borrowed and copied or was an rvalue whose storage could be transferred.
struct Mesh {
    std::vector<std::uint32_t> indices;
    bool copied_input;
    explicit Mesh(const std::vector<std::uint32_t>& input)
        : indices(input), copied_input(true) {}
    explicit Mesh(std::vector<std::uint32_t>&& input)
        : indices(std::move(input)), copied_input(false) {}
};

// The non-type template parameter is part of the actual texture type.
// Channel count is validated at compile time, while texel_count is checked
// at runtime because it comes from decoded input.
template <std::size_t Channels>
struct Texture {
    static_assert(Channels >= 1 && Channels <= 4, "supported channel counts: 1..4");
    std::array<std::uint8_t, Channels> first_texel{};
    std::size_t texel_count{};
};

// A declared, undefined primary trait does NOT claim every C++ type is an
// asset. An explicit specialization enables Mesh; a partial specialization
// enables every supported Texture<Channels> family member.
template <class T>
struct AssetTraits;

template <>
struct AssetTraits<Mesh> {
    static constexpr std::string_view label = "mesh";
    static std::size_t byte_size(const Mesh& mesh) {
        constexpr std::size_t element_size = sizeof(std::uint32_t);
        if (mesh.indices.size() > std::numeric_limits<std::size_t>::max() / element_size)
            throw std::overflow_error("mesh size overflow");
        return mesh.indices.size() * element_size;
    }
};

template <std::size_t Channels>
struct AssetTraits<Texture<Channels>> {
    static constexpr std::string_view label = "texture";
    static std::size_t byte_size(const Texture<Channels>& texture) {
        if (texture.texel_count > std::numeric_limits<std::size_t>::max() / Channels)
            throw std::overflow_error("texture size overflow");
        return texture.texel_count * Channels;
    }
};

// A requires-expression tests well-formedness and result types. It does not
// run byte_size(), so data-dependent overflow still needs runtime checking.
template <class T>
concept Uploadable = requires(const T& asset) {
    { AssetTraits<T>::label } -> std::convertible_to<std::string_view>;
    { AssetTraits<T>::byte_size(asset) } -> std::same_as<std::size_t>;
};

struct UnknownAsset {};
static_assert(Uploadable<Mesh>);
static_assert(Uploadable<Texture<3>>);
static_assert(Uploadable<Texture<4>>);
static_assert(!Uploadable<UnknownAsset>);

// This is the earlier SFINAE idiom: when substitution of an expression fails,
// specialization is removed instead of producing a hard error in this context.
template <class T, class = void>
struct HasByteSize : std::false_type {};

template <class T>
struct HasByteSize<T, std::void_t<decltype(AssetTraits<T>::byte_size(
                                       std::declval<const T&>()))>> : std::true_type {};

static_assert(HasByteSize<Mesh>::value);
static_assert(HasByteSize<Texture<4>>::value);
static_assert(!HasByteSize<UnknownAsset>::value);

// Two viable function templates have otherwise equivalent parameter patterns.
// For Uploadable types, the constrained overload is the more specialized one.
template <class T>
constexpr std::string_view route(const T&) { return "unsupported"; }

template <Uploadable T>
constexpr std::string_view route(const T&) { return AssetTraits<T>::label; }

// A function template deduces T from the argument. No caller must write <Mesh>.
template <Uploadable T>
std::size_t asset_bytes(const T& asset) {
    return AssetTraits<T>::byte_size(asset);
}

// A comma fold evaluates each append from left to right. The empty pack is
// accepted and returns zero. All additions are checked for overflow.
template <Uploadable... T>
std::size_t total_bytes(const T&... assets) {
    std::size_t result = 0;
    [[maybe_unused]] const auto add_checked = [&result](std::size_t next) {
        if (next > std::numeric_limits<std::size_t>::max() - result)
            throw std::overflow_error("batch size overflow");
        result += next;
    };
    (add_checked(asset_bytes(assets)), ...);
    return result;
}

struct AssetId { std::size_t slot; };

// Class template: T specifies the stored semantic type; Capacity is a
// non-type template argument. A fixed array makes stable slots explicit.
// This is not a network format or a GPU resource descriptor.
template <Uploadable T, std::size_t Capacity>
class AssetDepot {
    static_assert(Capacity > 0, "at least one asset slot is required");
    std::array<std::optional<T>, Capacity> slots_{};
    std::size_t count_ = 0;
public:
    std::size_t size() const noexcept { return count_; }
    static constexpr std::size_t capacity() noexcept { return Capacity; }

    // Args&& are forwarding references because Args are deduced here.
    // std::forward<Args> preserves the original argument categories.
    // Construct into the next *unpublished* optional; increment count only
    // after construction succeeds. Existing assets stay untouched on throw.
    template <class... Args>
        requires std::constructible_from<T, Args&&...>
    AssetId emplace(Args&&... args) {
        if (count_ == Capacity) throw std::length_error("asset depot full");
        slots_[count_].emplace(std::forward<Args>(args)...);
        return AssetId{count_++};
    }

    const T& get(AssetId id) const {
        if (id.slot >= count_) throw std::out_of_range("invalid asset slot");
        return *slots_[id.slot]; // only slots below count_ are engaged
    }
};

// The language's reference-collapsing rules make T deduce as U& for an
// lvalue, and U for an rvalue; T&& then collapses respectively to U& or U&&.
template <class T>
constexpr bool was_lvalue(T&&) { return std::is_lvalue_reference_v<T>; }

// A failed constrained call can be queried instead of being compiled as an
// intentionally broken expression. This also verifies the actual API surface.
template <class Store, class... Args>
concept CanEmplace = requires(Store& store, Args&&... args) {
    { store.emplace(std::forward<Args>(args)...) } -> std::same_as<AssetId>;
};

using MeshDepot = AssetDepot<Mesh, 2>;
static_assert(CanEmplace<MeshDepot, std::vector<std::uint32_t>&>);
static_assert(CanEmplace<MeshDepot, std::vector<std::uint32_t>>);
static_assert(!CanEmplace<MeshDepot, int>);

// A throwing asset makes the unpublished-slot invariant observable.
struct CheckedShader {
    int version;
    explicit CheckedShader(int v) : version(v) {
        if (v <= 0) throw std::invalid_argument("shader version must be positive");
    }
};

template <>
struct AssetTraits<CheckedShader> {
    static constexpr std::string_view label = "shader";
    static std::size_t byte_size(const CheckedShader&) { return sizeof(int); }
};

void run() {
    MeshDepot meshes;
    std::vector<std::uint32_t> input{3, 7, 9};
    require(was_lvalue(input), "lvalue category should be preserved");
    require(!was_lvalue(std::vector<std::uint32_t>{}), "temporary is an rvalue");

    // An lvalue chooses the const& constructor, making a semantic copy.
    const AssetId copied = meshes.emplace(input);
    require(meshes.get(copied).copied_input, "lvalue copied, not moved");
    require(input.size() == 3, "copy leaves the original usable");

    // An rvalue chooses the && constructor, making the source transferable.
    const AssetId moved = meshes.emplace(std::move(input));
    require(!meshes.get(moved).copied_input, "rvalue selects move path");
    require(meshes.get(moved).indices.size() == 3, "moved payload is retained");
    // Do not assume a moved-from vector has a particular size.

    bool full_rejected = false;
    try { meshes.emplace(std::vector<std::uint32_t>{11}); }
    catch (const std::length_error&) { full_rejected = true; }
    require(full_rejected && meshes.size() == 2, "full store preserves prior assets");

    AssetDepot<CheckedShader, 2> shaders;
    const AssetId good = shaders.emplace(3);
    bool bad_rejected = false;
    try { shaders.emplace(-1); }
    catch (const std::invalid_argument&) { bad_rejected = true; }
    require(bad_rejected && shaders.size() == 1, "throwing construction stays unpublished");
    require(shaders.get(good).version == 3, "prior shader is intact");
    const AssetId second = shaders.emplace(4);
    require(second.slot == 1 && shaders.size() == 2, "failed slot can be reused");

    Texture<4> rgba{{255, 0, 128, 255}, 12};
    Texture<3> rgb{{12, 23, 34}, 5};
    require(asset_bytes(meshes.get(copied)) == 3 * sizeof(std::uint32_t),
            "mesh trait counts stored indices");
    require(asset_bytes(rgba) == 48 && asset_bytes(rgb) == 15,
            "texture partial specialization accounts for channels");
    require(total_bytes(meshes.get(copied), rgba, rgb) == 75,
            "heterogeneous checked comma fold sums bytes");
    require(total_bytes() == 0, "empty fold produces zero");
    require(route(rgba) == "texture", "constrained overload wins for Texture");
    require(route(meshes.get(copied)) == "mesh", "constrained overload wins for Mesh");
    require(route(UnknownAsset{}) == "unsupported", "fallback is deliberate");

    bool overflow_rejected = false;
    Texture<4> enormous{{0, 0, 0, 0}, std::numeric_limits<std::size_t>::max()};
    try { (void)asset_bytes(enormous); }
    catch (const std::overflow_error&) { overflow_rejected = true; }
    require(overflow_rejected, "runtime byte-size overflow is checked");

    std::cout << "generic_asset_pipeline_lab: all checks passed\n";
}
} // namespace allmight

int main() {
    try { allmight::run(); }
    catch (const std::exception& error) {
        std::cerr << "generic_asset_pipeline_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// Independent C++20 disk event-pipeline laboratory, not the Kairo production solver.
// Units: metres, seconds, kilograms; 2D non-spinning disks moving at constant
// velocity between instantaneous, frictionless, normal impulses.
// Build: c++ -std=c++20 -O2 -Wall -Wextra -Wpedantic -Werror disk_event_pipeline_lab.cpp -o /tmp/disk_events && /tmp/disk_events
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <limits>
#include <optional>
#include <utility>
#include <stdexcept>
#include <vector>

struct Vec2 { double x{}, y{}; };
constexpr Vec2 operator+(Vec2 a, Vec2 b) { return {a.x+b.x,a.y+b.y}; }
constexpr Vec2 operator-(Vec2 a, Vec2 b) { return {a.x-b.x,a.y-b.y}; }
constexpr Vec2 operator*(Vec2 a, double s) { return {a.x*s,a.y*s}; }
constexpr double dot(Vec2 a, Vec2 b) { return a.x*b.x+a.y*b.y; }
void check(bool b, const char* msg) { if (!b) throw std::runtime_error(msg); }
void near(double a,double b,double epsilon=1e-8) {
    check(std::isfinite(a)&&std::isfinite(b)&&std::abs(a-b)<=epsilon,"numerical invariant failed");
}
struct Disk {
    std::uint64_t id{};
    Vec2 centre{},velocity{};
    double radius{}, inverseMass{};
};
void validate(const Disk& d) {
    check(std::isfinite(d.centre.x)&&std::isfinite(d.centre.y)&&
          std::isfinite(d.velocity.x)&&std::isfinite(d.velocity.y)&&
          std::isfinite(d.radius)&&d.radius>0&&
          std::isfinite(d.inverseMass)&&d.inverseMass>=0,"invalid disk");
}
Vec2 unit(Vec2 v) {
    const double length=std::hypot(v.x,v.y);
    check(std::isfinite(length)&&length>0,"contact has undefined normal");
    return v*(1.0/length);
}
// All inputs are checked by simulate(). This root is stable in the approaching case.
// An initial overlap is rejected by the caller: this witness solves *new impacts*,
// not position stabilization. Touching disks are considered only if closing.
std::optional<double> time_of_impact(const Disk& a,const Disk& b,double duration) {
    const Vec2 p=b.centre-a.centre, v=b.velocity-a.velocity;
    const double radius=a.radius+b.radius;
    const double c=dot(p,p)-radius*radius;
    const double aa=dot(v,v),bb=2*dot(p,v);
    check(std::isfinite(c)&&std::isfinite(aa)&&std::isfinite(bb),"nonfinite geometry");
    // Relative tolerance addresses near-touch floating error in successive events.
    // The subtraction of world-space centres can lose bits at large translations.
    // Compare a *linear* surface gap against a length-scale error budget, not
    // squared-distance error against a fixed radius-scale tolerance.
    const double distance=std::hypot(p.x,p.y);
    const double coordinateScale=std::max({1.0,radius,
        std::hypot(a.centre.x,a.centre.y),std::hypot(b.centre.x,b.centre.y)});
    const double tolerance=128*std::numeric_limits<double>::epsilon()*coordinateScale;
    check(std::isfinite(distance)&&std::isfinite(tolerance),"nonfinite contact distance");
    check(distance>=radius-tolerance,"pre-existing geometric overlap; stabilization required");
    if(distance<=radius+tolerance) {
        if(bb>=0)return std::nullopt;
        return 0.0;
    }
    if(aa==0||bb>=0)return std::nullopt;
    const double discriminant=std::fma(bb,bb,-4*aa*c);
    if(discriminant<0)return std::nullopt;
    const double root=std::sqrt(discriminant);
    const double q=-0.5*(bb-root); // bb<0 means q>0.
    if(!(q>0))return std::nullopt;
    const double t=c/q;
    if(!std::isfinite(t)||t<0||t>duration)return std::nullopt;
    // A grazing contact has zero closing normal velocity and needs no impulse.
    const Vec2 atImpact=p+v*t;
    if(dot(v,atImpact)>=0)return std::nullopt;
    return t;
}
struct Event { std::size_t a{},b{}; double t{}; Vec2 normal{}; double targetSpeed{},impulse{}; };
struct Result { std::size_t events{},batches{}; double simulated{}; };
// The event cap is a safety boundary: hitting it raises an error, never silently
// advances through unresolved contacts. All simultaneous candidates are collected
// deterministically by pair order and their initial restitution targets are frozen.
// Build swept-AABB candidate pairs for the *current* remaining interval.
// The reference all-pairs mode is retained for differential testing.
// A broadphase false positive is allowed; a false negative is not.
using DiskPair = std::pair<std::size_t,std::size_t>;
std::vector<DiskPair> candidate_pairs_for_step(const std::vector<Disk>& disks,
                                                double remaining, bool swept) {
    std::vector<DiskPair> pairs;
    if(!swept) {
        for(std::size_t i=0;i<disks.size();++i)
            for(std::size_t j=i+1;j<disks.size();++j)
                pairs.emplace_back(i,j);
        return pairs;
    }
    struct SweptBox {
        double minX,maxX,minY,maxY;
        std::size_t index;
    };
    std::vector<SweptBox> boxes;
    boxes.reserve(disks.size());
    for(std::size_t i=0;i<disks.size();++i) {
        const auto& d=disks[i];
        const double xEnd=std::fma(d.velocity.x,remaining,d.centre.x);
        const double yEnd=std::fma(d.velocity.y,remaining,d.centre.y);
        check(std::isfinite(xEnd)&&std::isfinite(yEnd),"swept endpoint overflow");
        const double negative=-std::numeric_limits<double>::infinity();
        const double positive=std::numeric_limits<double>::infinity();
        SweptBox b{
            std::nextafter(std::min(d.centre.x,xEnd)-d.radius,negative),
            std::nextafter(std::max(d.centre.x,xEnd)+d.radius,positive),
            std::nextafter(std::min(d.centre.y,yEnd)-d.radius,negative),
            std::nextafter(std::max(d.centre.y,yEnd)+d.radius,positive),i
        };
        check(std::isfinite(b.minX)&&std::isfinite(b.maxX)&&
              std::isfinite(b.minY)&&std::isfinite(b.maxY),"invalid swept box");
        boxes.push_back(b);
    }
    // Stable body IDs break ties so the sweep itself is repeatable.
    std::sort(boxes.begin(),boxes.end(),[&](const SweptBox& a,const SweptBox& b) {
        if(a.minX!=b.minX)return a.minX<b.minX;
        return disks[a.index].id<disks[b.index].id;
    });
    std::vector<SweptBox> active;
    for(const SweptBox& b:boxes) {
        active.erase(std::remove_if(active.begin(),active.end(),[&](const SweptBox& a) {
            return a.maxX<b.minX;
        }),active.end());
        for(const auto& a:active) {
            if(a.minY<=b.maxY && b.minY<=a.maxY)
                pairs.emplace_back(std::min(a.index,b.index),std::max(a.index,b.index));
        }
        active.push_back(b);
    }
    // Crucial for deterministic comparison: TOI queries must execute in the
    // same original index-pair order as the exhaustive reference implementation.
    std::sort(pairs.begin(),pairs.end());
    check(std::adjacent_find(pairs.begin(),pairs.end())==pairs.end(),
          "duplicate swept pair");
    return pairs;
}

Result simulate(std::vector<Disk>& disks,double dt,double restitution=1,
                std::size_t maxEvents=256,bool useSweptBroadphase=false) {
    check(std::isfinite(dt)&&dt>=0&&std::isfinite(restitution)&&
          restitution>=0&&restitution<=1,"invalid time or restitution");
    for(const auto& disk:disks)validate(disk);
    for(std::size_t i=0;i<disks.size();++i)
        for(std::size_t j=i+1;j<disks.size();++j)
            check(disks[i].id!=disks[j].id,"duplicate stable body id");
    double remaining=dt;
    Result result{};
    while(remaining>0) {
        double first=std::numeric_limits<double>::infinity();
        std::vector<Event> candidates;
        // Recompute broadphase candidates after every impact because velocities change.
        // The all-pairs mode remains the independent reference.
        for(const auto& [i,j] : candidate_pairs_for_step(disks,remaining,useSweptBroadphase)) {
            const auto hit=time_of_impact(disks[i],disks[j],remaining);
            if(!hit)continue;
            if(*hit<first)first=*hit;
            candidates.push_back({i,j,*hit});
        }
        if(!std::isfinite(first)) {
            for(auto& d:disks)d.centre=d.centre+d.velocity*remaining;
            result.simulated+=remaining;
            break;
        }
        // Include simultaneous impacts within the declared time tolerance.
        const double epsTime=64*std::numeric_limits<double>::epsilon()*std::max(1.0,dt);
        std::vector<Event> batch;
        for(auto e:candidates)if(std::abs(e.t-first)<=epsTime)batch.push_back(e);
        check(!batch.empty(),"event collection failure");
        check(batch.size()<=maxEvents-result.events,"event budget exhausted");
        for(auto& d:disks)d.centre=d.centre+d.velocity*first;
        remaining-=first;
        result.simulated+=first;
        for(auto& e:batch) {
            auto& a=disks[e.a];auto& b=disks[e.b];
            e.normal=unit(b.centre-a.centre);
            const double speed=dot(b.velocity-a.velocity,e.normal);
            check(speed<0,"non-closing event selected");
            e.targetSpeed=-restitution*speed; // frozen pre-solve value
        }
        // Projected iterative normal impulses: handles simultaneous shared bodies.
        for(int iteration=0;iteration<32;++iteration)for(auto& e:batch) {
            auto& a=disks[e.a];auto& b=disks[e.b];
            const double inverseMass=a.inverseMass+b.inverseMass;
            if(inverseMass==0)continue;
            const double vn=dot(b.velocity-a.velocity,e.normal);
            const double updated=std::max(0.0,e.impulse+(e.targetSpeed-vn)/inverseMass);
            const double delta=updated-e.impulse;
            e.impulse=updated;
            a.velocity=a.velocity-e.normal*(delta*a.inverseMass);
            b.velocity=b.velocity+e.normal*(delta*b.inverseMass);
        }
        result.events+=batch.size();
        ++result.batches;
        // At t=0 a resolved separating/tangent pair must be skipped by the next TOI.
        // If it remains closing due to insufficient convergence, cap catches the loop.
    }
    return result;
}
Vec2 momentum(const std::vector<Disk>& ds) {
    Vec2 p{};
    for(const auto& d:ds)if(d.inverseMass>0)p=p+d.velocity*(1/d.inverseMass);
    return p;
}
double energy(const std::vector<Disk>& ds) {
    double e=0;
    for(const auto& d:ds)if(d.inverseMass>0)e+=dot(d.velocity,d.velocity)/(2*d.inverseMass);
    return e;
}
#ifndef ALLMIGHT_EVENT_PIPELINE_NO_MAIN
int main() {
    {
        std::vector<Disk> ds{{1,{0,0},{0,0},1,0},{2,{10,0},{-100,0},1,1}};
        const auto r=simulate(ds,0.1,1);
        check(r.events==1&&r.batches==1,"fast wall event missing");
        near(ds[1].centre.x,4);near(ds[1].velocity.x,100);
        near(r.simulated,0.1);
    }
    {
        std::vector<Disk> ds{{1,{-4,0},{2,0},1,1},{2,{4,0},{-2,0},1,1}};
        const auto p=momentum(ds);const auto k=energy(ds);
        const auto r=simulate(ds,2,1);
        check(r.events==1,"two disk collision count");
        near(ds[0].velocity.x,-2);near(ds[1].velocity.x,2);
        near(momentum(ds).x,p.x);near(energy(ds),k);
    }
    {
        // Three disks arrive simultaneously: both constraint rows share the middle mass.
        std::vector<Disk> ds{{1,{-4,0},{1,0},1,1},{2,{0,0},{0,0},1,1},
                             {3,{4,0},{-1,0},1,1}};
        const auto before=momentum(ds); const double k=energy(ds);
        const auto r=simulate(ds,3,1);
        check(r.events==2&&r.batches==1,"simultaneous batch missed");
        near(ds[0].velocity.x,-1,1e-7);near(ds[1].velocity.x,0,1e-7);
        near(ds[2].velocity.x,1,1e-7);
        near(momentum(ds).x,before.x);near(energy(ds),k,1e-7);
    }
    {
        std::vector<Disk> ds{{1,{0,0},{1,0},1,1},{2,{10,0},{2,0},1,1}};
        const auto r=simulate(ds,2);
        check(r.events==0,"separating contacts should not collide");
        near(ds[0].centre.x,2);near(ds[1].centre.x,14);
    }
    {
        // No implicit correction of pre-existing deep overlap.
        std::vector<Disk> ds{{1,{0,0},{0,0},1,1},{2,{1,0},{0,0},1,1}};
        bool rejected=false;
        try{(void)simulate(ds,0.5);}catch(const std::runtime_error&){rejected=true;}
        check(rejected,"initial overlap was not rejected");
    }
    {
        std::vector<Disk> ds{{1,{-4,0},{2,0},1,1},{2,{4,0},{-2,0},1,1}};
        bool rejected=false;
        try{(void)simulate(ds,2,1,0);}catch(const std::runtime_error&){rejected=true;}
        check(rejected,"event budget failure was silent");
    }
    {
        // The first impact starts a second event later in the same frame.
        std::vector<Disk> ds{{1,{-6,0},{4,0},1,1},{2,{0,0},{0,0},1,1},
                             {3,{6,0},{0,0},1,1}};
        const auto r=simulate(ds,3,1);
        check(r.events==2&&r.batches==2,"sequential event rescheduling failed");
        near(ds[0].velocity.x,0);near(ds[1].velocity.x,0);
        near(ds[2].velocity.x,4);near(momentum(ds).x,4);
    }
    {
        // Perfectly inelastic velocity-level impact preserves momentum but loses energy.
        std::vector<Disk> ds{{1,{-3,0},{2,0},1,1},{2,{3,0},{0,0},1,1}};
        const auto originalMomentum=momentum(ds).x;
        const auto initialEnergy=energy(ds);
        const auto r=simulate(ds,2,0);
        check(r.events==1,"inelastic impact not detected");
        near(ds[0].velocity.x,1);near(ds[1].velocity.x,1);
        near(momentum(ds).x,originalMomentum);
        check(energy(ds)<initialEnergy,"inelastic impact gained energy");
    }
    {
        // Stable IDs must not alias; zero-duration steps must not mutate velocities.
        std::vector<Disk> ds{{1,{0,0},{1,0},1,1},{2,{10,0},{0,0},1,1}};
        const auto r=simulate(ds,0);
        check(r.events==0,"zero duration generated event");
        near(ds[0].centre.x,0);
        ds[1].id=1;
        bool rejected=false;
        try{(void)simulate(ds,1);}catch(const std::runtime_error&){rejected=true;}
        check(rejected,"duplicate stable identities accepted");
    }
    std::cout << "disk event pipeline: 9 scene suites PASS\n";
}
#endif // ALLMIGHT_EVENT_PIPELINE_NO_MAIN

// Project AllMight M016 / Parts 251-270, C++20 executable reference.
// Extends the growing asset registry into a read-only query snapshot, typed
// results, ordered searches, deterministic reporting and safe erasure.
// No GPU submission, allocator benchmark or concurrent registry is claimed.
#include <algorithm>
#include <any>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <forward_list>
#include <functional>
#include <iostream>
#include <iterator>
