    try { allmight::run(); }
    catch (const std::exception& error) {
        std::cerr << "asset_query_algorithm_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// Project AllMight M015 / Parts 231-250.
// C++20 standalone laboratory: a growing asset registry, borrowed views,
// container invalidation, hash collisions, and scheduling adapters.
// This models CPU-side ownership. No GPU queue or native asset source is used.
#include <algorithm>
#include <array>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <forward_list>
#include <functional>
#include <iostream>
#include <limits>
#include <iterator>
#include <memory>
#include <list>
#include <map>
#include <optional>
#include <queue>
#include <set>
#include <span>
#include <stack>
#include <stdexcept>
#include <string>
#include <string_view>
#include <type_traits>
#include <unordered_map>
#include <unordered_set>
#include <utility>
