    expect_exception<std::domain_error>([]{ (void)divide(1,0); });
    expect_exception<std::overflow_error>([]{ (void)multiply(INT32_MAX,INT32_MAX); });
    expect_exception<std::overflow_error>([]{ (void)from_double(1e300); });
